#include <iostream>
#include <memory>
#include <fstream>

void file_deleter(std::FILE* file) {
  if (file) {
    std::fclose(file);
  }
}

int main() {
  std::shared_ptr<std::FILE> file(std::fopen("my_file.txt", "w"), file_deleter);
  if (file) {
    std::fprintf(file.get(), "Hello, world!\n");
  }
  // file will be automatically closed and the resource released even if exceptions occur.
  return 0;
}
